void nc_dump_tensor_hash(const char *name, const NCTensor *tensor)
{
    const char *directory = getenv("NNCP_INTERNAL_DUMP_DIR");
    NCTensor *cpu_tensor;
    NCTensorData data;
    char safe_name[128];
    char data_path[4096];
    char metadata_path[4096];
    FILE *output;
    size_t current;
    int axis;

    if (directory == NULL || directory[0] == '\0')
        return;
