    if (output == NULL ||
        write_axis(output, &data, data.data, data.n_dims - 1) != 0 ||
        fclose(output) != 0) {
        fprintf(stderr, "cannot write internal tensor %s\n", data_path);
        abort();
    }
    snprintf(metadata_path, sizeof(metadata_path), "%s/%03zu_%s.meta",
             directory, current, safe_name);
