            current, name, data.item_type, data.item_size);
    fprintf(output, "dims=");
    for (axis = 0; axis < data.n_dims; axis++)
        fprintf(output, "%s%zu", axis == 0 ? "" : ",", data.dims[axis]);
    fprintf(output, "\n");
    if (fclose(output) != 0)
        abort();
    nc_free_tensor(cpu_tensor);
}
